 const companies=companiesSeed.map((x,i)=>({id:`C${String(i+1).padStart(3,'0')}`,name:x[0],type:x[1],region:regions[i],leader:['李建国','王秀兰','赵文博','周建华','刘强','孙丽','马俊','陈海','高峰','许敏'][i],employees:8+i*3,status:i===9?'待审核':'正常',credit:88+(i*7)%12,transactions:18+i*13,created:dateAgo(24-i)}));
