 ['订单管理','orders','orders','交易履约'],['库存台账','warehouse','warehouse','仓储运输'],['运输协同','logistics','logistics',''],['称重记录','weighing','weighing',''],['批次追溯','trace','trace',''],
 ['资金对账','finance','finance','资金与票据'],['发票资料','invoices','invoice',''],
 ['企业档案','system','company','企业设置']
