function createTransport(orderId){let o=findOrder(orderId);if(!o)return toast('未找到订单','warn');let existing=findTrans(orderId);if(existing){toast('该订单已有运输任务');page='logistics';selectedVehicle=existing.vehicle;modal=null;render();return}let v=data.vehicles.find(x=>x.status==='空闲'||x.status==='待接单')||data.vehicles[0];let id=`YS-2026${String(data.transports.length+1).padStart(4,'0')}`;data.transports.unshift({id,vehicle:v.id,order:orderId,status:'待接单',progress:0,updated:`${today} 14:55`,exception:''});v.order=orderId;v.material=o.material;v.status='待接单';v.progress=0;v.speed=0;v.from=findCo(o.seller);v.to=findCo(o.buyer);v.lastUpdate=`${today} 14:55`;o.status='待发货';selectedVehicle=v.id;save(`为订单 ${orderId} 创建运输任务 ${id}`);page='logistics';modal=null;render();toast(`运输任务 ${id} 已创建，司机端可接单`)}
