function roleKind(){return data.activeUser?.kind||'admin'}
function roleCfg(){return roleInfo[roleKind()]||roleInfo.admin}
function ensureRoleIdentity(){if(!data.activeUser)return;let c=roleCfg();data.activeUser.personName=data.activeUser.personName||c.personName||data.activeUser.name;data.activeUser.userId=data.activeUser.userId||c.userId||'';if(data.activeUser.company===undefined)data.activeUser.company=c.company}
function roleNav(kind=roleKind()){return roleMenus[kind]||navAdmin}
function rolePageAllowed(key,kind=roleKind()){return key==='dashboard'||roleNav(kind).some(x=>x[1]===key)}
function roleCompanyOrders(companyId){return data.orders.filter(o=>o.seller===companyId||o.buyer===companyId)}
function roleOrders(kind=roleKind()){
  if(kind==='admin')return data.orders;
  if(kind==='company'||kind==='finance')return roleCompanyOrders(roleCfg().company);
  if(kind==='factory')return data.orders.filter(o=>o.buyer===roleCfg().company);
  if(kind==='warehouse')return roleCompanyOrders(roleCfg().company);
  if(kind==='driver'){let ids=new Set(roleCfg().vehicleIds||[]);let tids=new Set(data.transports.filter(t=>ids.has(t.vehicle)).map(t=>t.order));return data.orders.filter(o=>tids.has(o.id))}
  if(kind==='recycler'){let bset=new Set(data.batches.filter(b=>b.recycler===roleCfg().personName||b.recyclerId===roleCfg().userId).map(b=>b.order));return data.orders.filter(o=>bset.has(o.id))}
  return []
}
function roleOrderIds(kind=roleKind()){return new Set(roleOrders(kind).map(o=>o.id))}
function roleTransports(kind=roleKind()){
  let allowed=roleOrderIds(kind),vehicles=kind==='driver'?new Set(roleCfg().vehicleIds||[]):null;
  return data.transports.filter(t=>allowed.has(t.order)&&(!vehicles||vehicles.has(t.vehicle)))
}
function roleBatches(kind=roleKind()){
  let ids=roleOrderIds(kind);
  return data.batches.filter(b=>ids.has(b.order)||(kind==='recycler'&&(b.recycler===roleCfg().personName||b.recyclerId===roleCfg().userId)))
}
function roleWeighings(kind=roleKind()){let ids=roleOrderIds(kind);return data.weighings.filter(w=>ids.has(w.order)||roleBatches(kind).some(b=>b.id===w.batch))}
function roleSettlements(kind=roleKind()){let ids=roleOrderIds(kind);return data.settlements.filter(s=>ids.has(s.order))}
function roleInvoices(kind=roleKind()){let ids=roleOrderIds(kind);return data.invoices.filter(i=>ids.has(i.order))}
function roleVehicles(kind=roleKind()){
  let ids=new Set(roleTransports(kind).map(t=>t.vehicle));return kind==='admin'?data.vehicles:data.vehicles.filter(v=>ids.has(v.id))
}
