  if(kind==='factory')return [['我的采购订单',nfmt(os.length),'采购方限定为本厂','▤'],['采购金额',money(amt),'关联采购成交额','¥'],['待验收货物',nfmt(os.filter(o=>['待验收','运输中'].includes(o.status)).length),'到货复磅与质检','⚖'],['待付款',money(open.reduce((s,o)=>s+o.amount,0)),'采购订单待结算','◷']];
