function scopedOrderModal(){let k=roleKind(),isFactory=k==='factory',company=roleCfg().company,other=data.companies.filter(c=>c.id!==company);let materialOptions=materials.map(m=>`<option>${m}</option>`).join('');let party=isFactory?`<div class="form-field"><label>供应方（本厂采购）</label><select name="seller">${other.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></div><input type="hidden" name="buyer" value="${company}">`:`<input type="hidden" name="seller" value="${company}"><div class="form-field"><label>交易对方</label><select name="buyer">${other.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></div>`;openModal(isFactory?'新建本厂采购订单':'新建本企业订单',`<form data-form="role-order"><div class="form-grid"><div class="form-field"><label>材料</label><select name="material">${materialOptions}</select></div><div class="form-field"><label>等级</label><input name="grade" value="混合料A" required></div><div class="form-field"><label>数量（吨）</label><input name="qty" type="number" value="18" min="0.1" step="0.1" required></div><div class="form-field"><label>成交单价（元/吨）</label><input name="price" type="number" value="2480" min="1" required></div>${party}<div class="form-field full"><label>交付地点</label><input name="location" value="河北·石家庄 · 石门中转站"></div></div><div class="notice">卖方 / 买方已按当前企业岗位锁定。新订单只进入授权范围，可在其他端查询。</div></form>`,[{label:'取消',action:'modal-close'},{label:'创建关联订单',action:'submit-modal',cls:'primary'}])}
