function saveRoleOrder(obj,isCollection=false){let n=data.orders.length+1,qty=Number(obj.qty),price=Number(obj.price),id=`DD-${today.replaceAll('-','')}-${String(n).padStart(4,'0')}`,seller=isCollection?roleCfg().company:obj.seller,buyer=isCollection?'C002':obj.buyer;let order={id,material:obj.material,grade:obj.grade||'混合料A',qty,unit:'吨',price,amount:Math.round(qty*price),buyer,seller,status:isCollection?'待确认':'待确认',date:today,location:obj.location||'河北·石家庄',freight:Math.round(qty*32),quality:'按样验收，演示约定',settled:false,traceId:`RS-${today.replaceAll('-','')}-${String(data.batches.length+1).padStart(6,'0')}`};data.orders.unshift(order);let b={id:order.traceId,order:id,material:order.material,weight:Math.round(qty*1000),source:findCo(seller),recycler:isCollection?roleCfg().personName:'演示回收员',recyclerId:isCollection?roleCfg().userId:'',location:obj.location||'石门中转站',status:'待确认',created:`${today} ${new Date().toLocaleTimeString('zh-CN',{hour12:false}).slice(0,5)}`};data.batches.unshift(b);save(`${roleLabel()} ${isCollection?'登记回收':'创建订单'} ${id}，批次 ${b.id}`);modal=null;page='orders';mobileTab=window.matchMedia('(max-width:720px)').matches?'business':'home';render();toast('记录已创建，仅关联当前岗位企业/人员')}
function submitScopedForm(e){let f=e.target.closest('form[data-form]');if(!f)return;let type=f.dataset.form;if(!['role-order','role-collection','role-invoice'].includes(type))return;e.preventDefault();e.stopImmediatePropagation();let obj=Object.fromEntries(new FormData(f).entries());if(type==='role-order'){let k=roleKind();if(k==='factory')obj.buyer=roleCfg().company;else obj.seller=roleCfg().company;saveRoleOrder(obj,false);return}if(type==='role-collection'){saveRoleOrder(obj,true);return}let o=roleOrders().find(x=>x.id===obj.order);if(!o){toast('授权范围内没有可申请发票的订单','warn');return}let no=`FP-202611-${String(data.invoices.length+1).padStart(4,'0')}`;data.invoices.unshift({id:no,order:o.id,company:roleCfg().company,title:findCo(roleCfg().company),taxId:obj.taxId,amount:o.amount,type:obj.type,number:'—',status:'待申请',created:today});save(`为授权订单 ${o.id} 提交演示发票`);modal=null;page='invoices';render();toast('关联发票申请已生成')}
function confirmFactoryReceipt(){let o=roleOrders('factory').find(x=>['待验收','运输中','待发货'].includes(x.status));if(!o){toast('本厂授权采购订单中没有待验收货物','warn');return}o.status='待结算';let b=data.batches.find(x=>x.order===o.id);if(b){b.status='已验收';let ev=getEvents(b);ev.push({time:`${today} ${new Date().toLocaleTimeString('zh-CN',{hour12:false}).slice(0,5)}`,title:'本厂确认收货（模拟）',desc:`${findCo(roleCfg().company)} 确认采购订单 ${o.id} 到货。`});data.traceEvents[b.id]=ev}save(`工厂采购岗位确认收货 ${o.id}`);render();toast('本厂到货确认已同步到采购订单与批次')}
function interceptRoleActions(e){let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action,k=roleKind();
 if(a==='nav'&&!rolePageAllowed(el.dataset.page,k)){e.preventDefault();e.stopImmediatePropagation();toast('当前岗位无权进入该模块','warn');return}
 if(a==='mobile-tab'&&el.dataset.value==='business'&&!rolePageAllowed(page,k))page=firstBusinessPage(k);
 if(a==='order-create'&&['company','factory','recycler'].includes(k)){e.preventDefault();e.stopImmediatePropagation();if(k==='recycler')scopedCollectionModal();else scopedOrderModal();return}
 if(a==='collection-create'){e.preventDefault();e.stopImmediatePropagation();scopedCollectionModal();return}
 if(a==='invoice-apply'&&k!=='admin'){e.preventDefault();e.stopImmediatePropagation();if(roleOrders().length)scopedInvoiceModal();else toast('授权订单列表为空，暂不能申请发票','warn');return}
 if(a==='scan-demo'||a==='scan-open'){e.preventDefault();e.stopImmediatePropagation();let bs=roleBatches(),b=bs.find(x=>x.id===el.dataset.id)||bs[0];if(!b){toast('当前身份授权范围内没有可扫描批次','warn');return}openModal('授权范围批次扫码演示',`${qrMarkup(b.id)}<div class="notice blue">仅能打开当前岗位关联批次；演示图案不是实际可扫描二维码。</div>`,[{label:'打开本人可见批次',action:'trace-detail',id:b.id,cls:'primary'},{label:'关闭',action:'modal-close'}]);return}
 if(a==='user-add'&&k==='company'){e.preventDefault();e.stopImmediatePropagation();openModal('新增本企业演示员工',`<form data-form="role-user"><div class="form-grid"><div class="form-field"><label>姓名</label><input name="name" required></div><div class="form-field"><label>岗位</label><select name="role">${['采购','销售','仓库','司机','财务','质检','回收员'].map(x=>`<option>${x}</option>`).join('')}</select></div><input type="hidden" name="company" value="${roleCfg().company}"><div class="form-field full"><label>所属企业</label><input value="${esc(findCo(roleCfg().company))}" disabled></div></div><div class="notice">新员工固定归属当前企业，其他企业不可选。</div></form>`,[{label:'取消',action:'modal-close'},{label:'保存员工',action:'submit-modal',cls:'primary'}]);return}
 if(a==='stock-in'&&['warehouse','company'].includes(k)){e.preventDefault();e.stopImmediatePropagation();let b=roleBatches().find(x=>x.status!=='库存中');if(!b){toast('当前岗位范围没有待入库批次','warn');return}b.status='库存中';b.weight+=180;let ev=getEvents(b);ev.push({time:`${today} ${new Date().toLocaleTimeString('zh-CN',{hour12:false}).slice(0,5)}`,title:'模拟入库',desc:`${b.location} 完成批次 ${b.id} 入库，库存 +180 kg。`});data.traceEvents[b.id]=ev;save(`授权批次 ${b.id} 模拟入库`);render();toast(`批次 ${b.id} 已入库`);return}
 if(a==='inventory-count'&&['warehouse','company'].includes(k)){e.preventDefault();e.stopImmediatePropagation();let b=roleBatches()[0];if(!b){toast('当前岗位范围没有可盘点批次','warn');return}let risk={id:`FX-${String(data.risks.length+1).padStart(4,'0')}`,type:'库存盘点差异待核查',company:findCo(roleCfg().company),order:b.order,time:`${today} ${new Date().toLocaleTimeString('zh-CN',{hour12:false}).slice(0,5)}`,description:`演示盘点批次 ${b.id} 显示差异 0.3 吨，需现场复核；不自动判定异常。`,status:'待处理',handler:roleCfg().personName};data.risks.unshift(risk);save(`授权批次 ${b.id} 生成盘点待核查事件`);render();toast('已生成当前范围内的盘点待核查事件');return}
 if(a==='factory-receive'&&k==='factory'){e.preventDefault();e.stopImmediatePropagation();confirmFactoryReceipt();return}
 if(a==='settle-next'&&['finance','company'].includes(k)){e.preventDefault();e.stopImmediatePropagation();let pending=roleSettlements(k).find(s=>s.status==='待结算'),o=pending?findOrder(pending.order):roleOrders(k).find(x=>!x.settled);if(!o){toast('本企业没有待结算账单','warn');return}settleOrder(o.id);return}
}
